<template>
  <AppLabeledSelectQuery
    :value="selectorValue"
    :null-is-all="false"
    :property-name="`${propertyName.start}|${propertyName.end}`"
    :items="dateRangeSelectorItems"
    :change-page="false"
    element-width="sm:w-fit"
  />
  <AppRangeDatePickerQuery
    :value="{
      start: params.startDate || defaultDate.startDate,
      end: params.endDate || defaultDate.endDate,
    }"
    :property-names="{ start: propertyName.start, end: propertyName.end }"
    :change-page="false"
    :is-iso-format="true"
    :clear-button="!Boolean(params.startDate === defaultDate.startDate && params.endDate === defaultDate.endDate)"
    element-width="w-full sm:w-fit"
  />
</template>

<script setup lang="ts">
import type { DateRangeKey } from '~/constants/dateRangeSelector';
import { isSameDay, differenceInCalendarDays } from 'date-fns';
import { dateRangeData } from '~/constants/dateRangeSelector';

interface Props {
  params: { startDate: string; endDate: string };
  defaultDate: { startDate: string; endDate: string };
  allTimeDate?: { startDate: string; endDate: string };
  excludeSelectorItems: DateRangeKey[];
  propertyName?: { start: string; end: string };
}

const props = withDefaults(defineProps<Props>(), {
  propertyName: () => ({ start: 'start_date', end: 'end_date' }),
  allTimeDate: undefined,
});

const dateRangeSelectorItems = ref<SelectItem[]>(processRangeSelectorItems());

onBeforeRouteUpdate(() => {
  dateRangeSelectorItems.value = processRangeSelectorItems();
});

onUnmounted(() => {
  dateRangeSelectorItems.value = [];
});

onBeforeMount(() => {
  dateRangeSelectorItems.value = processRangeSelectorItems();
});

function processRangeSelectorItems(): SelectItem[] {
  const today = formatDateToFormat(new Date().toISOString(), 'yyyy-MM-dd');
  return Object.entries(dateRangeData)
    .map(([_, { name, value, daysGap }]) => {
      if (props.excludeSelectorItems.includes(value)) return undefined;
      if (value === 'custom') {
        return {
          name: name,
          value: null,
          disabled: true,
        };
      } else if (typeof daysGap === 'number') {
        const startDate = dateFromNowWithDaysGap(new Date(), daysGap);
        const processedStartDate = formatDateToFormat(startDate, 'yyyy-MM-dd');
        return {
          name: name,
          value: `${processedStartDate}|${today}`,
        };
      } else if (value === 'all_time' && props.allTimeDate) {
        return {
          name: name,
          value: `${props.allTimeDate.startDate}|${props.allTimeDate.endDate}`,
        };
      }
    })
    .filter((item) => item !== undefined);
}

const selectorValue = computed(() => {
  const processedEndDate =
    props.params.endDate && isSameDay(new Date(), props.params.endDate)
      ? formatDateToFormat(new Date(), 'yyyy-MM-dd')
      : props.params.endDate;
  if (props.params.endDate && props.params.startDate && isSameDay(new Date(), props.params.endDate)) {
    const diffInDays = differenceInCalendarDays(props.params.endDate, props.params.startDate);
    const isNotCustom = Object.entries(dateRangeData)
      .map(([_, { daysGap }]) => daysGap)
      .filter((item) => item !== null)
      .includes(diffInDays);
    if (isNotCustom) return `${props.params.startDate}|${processedEndDate}`;
  }
  if (props.params.startDate === props.defaultDate.startDate && props.params.endDate === props.defaultDate.endDate)
    return `${props.params.startDate}|${props.params.endDate}`;
  return null;
});
</script>
